  form.addEventListener('submit',event=>{event.preventDefault();if(!form.reportValidity())return;const data=new FormData(form),name=String(data.get('name')).trim();if(!name){form.elements.name.setCustomValidity('Please enter your name.');form.elements.name.reportValidity();return;}
    const lines=[`Hello aRa Events & Studio! I’m ${name}.`,`I’m planning: ${data.get('occasion')}.`,data.get('date')?`Event date: ${data.get('date')}`:'Event date: To be discussed',`Interested in: ${data.getAll('services').join(', ')||'I would like your guidance'}`,data.get('message')?`My idea: ${String(data.get('message')).trim()}`:'','Could we discuss availability and a quotation?'].filter(Boolean);
    const url=`https://wa.me/919994447791?text=${encodeURIComponent(lines.join('\n'))}`;window.open(url,'_blank','noopener,noreferrer');const status=document.getElementById('form-status');status.replaceChildren(document.createTextNode('Your message is ready. If WhatsApp did not open, '));const a=document.createElement('a');a.href=url;a.target='_blank';a.rel='noopener noreferrer';a.textContent='open your WhatsApp draft here';a.style.textDecoration='underline';status.append(a,document.createTextNode('. Review it before sending.'));
  });form.elements.name.addEventListener('input',()=>form.elements.name.setCustomValidity(''));
  const services={
    photo:{image:'collection/couple-portrait.webp',alt:'A South Indian couple in traditional dress',caption:'The moments between the moments.',description:'The big emotions. The almost-missed glances. Photography for celebrations, portraits and the stories you want to hold on to.',cta:'Talk about your shoot',service:'Photography & films'},
    film:{image:'portal/last.webp',alt:'An AI-generated cinematic wedding venue with floral arches',caption:'A story you can feel again.',description:'From the first look to the last dance. Videography that brings the movement, atmosphere and emotion of your celebration back to life.',cta:'Discuss your film',service:'Photography & films'},
    decor:{image:'wedding-reception.webp',alt:'A warm ivory and gold reception room with floral decoration',caption:'A setting for your story.',description:'Flowers, light and thoughtful details that make a space feel like your celebration. Share the colours, mood and occasion you have in mind.',cta:'Imagine your setting',service:'Decoration & styling'},
    catering:{image:'collection/cuisine-spread.webp',alt:'A colourful spread of modern Indian-inspired dishes',caption:'Good food. Great company.',description:'Bring people together around the table. Talk to us about your guest count, preferences and the dining experience you’re imagining.',cta:'Discuss your menu',service:'Catering'},
    dj:{image:'dj-night.webp',alt:'A DJ performing under dramatic lights',caption:'The soundtrack to your night.',description:'Set the energy for the evening. Tell us about your crowd, the occasion and the kind of music that gets everyone moving.',cta:'Set the mood',service:'DJ & celebrations'},
    advertising:{image:'collection/bridal-portrait.webp',alt:'Illustrative studio portrait with carefully composed light',caption:'Make your message memorable.',description:'Visual stories for your brand, product or next announcement. Let’s discuss your audience, your message and what you want people to remember.',cta:'Share your brief',service:'Advertising'}
  };
  const tabs=[...document.querySelectorAll('[data-service-tab]')];tabs.forEach(tab=>tab.disabled=false);const orientation=()=>document.querySelector('.service-tabs').setAttribute('aria-orientation',innerWidth<=700?'horizontal':'vertical');orientation();addEventListener('resize',orientation);const panel=document.getElementById('service-panel'),image=document.getElementById('service-image');let activeService='photo',serviceRequest=0;
  const arrowMarkup=document.querySelector('#service-enquire svg').outerHTML;
  function selectService(tab,focus=false){const key=tab.dataset.serviceTab;if(!services[key])return;const next=services[key];tabs.forEach(el=>{const selected=el===tab;el.setAttribute('aria-selected',String(selected));el.tabIndex=selected?0:-1;});panel.setAttribute('aria-labelledby',tab.id);if(focus)tab.focus();
    const request=++serviceRequest;const preload=new Image();preload.src=`assets/${next.image}`;preload.decode().then(()=>{if(request!==serviceRequest)return;image.src=preload.src;image.alt=next.alt;if(!motionOff()&&window.gsap)gsap.fromTo(image,{scale:1.035,opacity:.65},{scale:1,opacity:1,duration:.65,ease:'power3.out',overwrite:true});}).catch(()=>{});document.getElementById('service-caption').textContent=next.caption;document.getElementById('service-description').textContent=next.description;const link=document.getElementById('service-enquire');link.innerHTML=next.cta+' '+arrowMarkup;link.dataset.service=next.service;
    activeService=key;
  }
  tabs.forEach((tab,index)=>{tab.addEventListener('click',()=>selectService(tab));tab.addEventListener('keydown',event=>{let next=index;if(event.key==='ArrowDown'||event.key==='ArrowRight')next=(index+1)%tabs.length;else if(event.key==='ArrowUp'||event.key==='ArrowLeft')next=(index+tabs.length-1)%tabs.length;else if(event.key==='Home')next=0;else if(event.key==='End')next=tabs.length-1;else return;event.preventDefault();selectService(tabs[next],true);});});
  let lenis,film,carousel,carouselModule,motionContext,stopped=false;const tick=time=>lenis?.raf(time*1000);
  const splitHeadings=[];
  function splitHeading(el){const label=[...el.childNodes].map(n=>n.nodeName==='BR'?' ':n.textContent).join('').replace(/\s+/g,' ').trim();el.setAttribute('aria-label',label);const fragment=document.createDocumentFragment();const words=[];[...el.childNodes].forEach(node=>{if(node.nodeName==='BR'){fragment.append(document.createElement('br'));return;}const chunks=node.textContent.split(/(\s+)/);chunks.forEach(text=>{if(!text)return;if(/^\s+$/.test(text)){fragment.append(document.createTextNode(text));return;}const clip=document.createElement('span');clip.className='word-clip';clip.setAttribute('aria-hidden','true');const word=document.createElement('span');word.className='motion-word';if(node.nodeName==='EM')word.style.fontStyle='italic';word.textContent=text;clip.append(word);fragment.append(clip);words.push(word);});});const original=el.innerHTML;el.replaceChildren(fragment);splitHeadings.push({el,original});return words;}
  function portalProgress(p){const opening=Math.max(0,Math.min(1,(p-.015)/.24));const ending=Math.max(0,Math.min(1,(p-.68)/.22));const copy=document.querySelector('.portal-copy');copy.style.opacity=String(1-opening);copy.style.visibility=opening>=1?'hidden':'visible';copy.style.transform=innerWidth<=700?`translateY(${-opening*20}px)`:`translateY(calc(-40% - ${opening*28}px))`;
    const wordmark=hero.querySelector('.hero-wordmark');if(wordmark)wordmark.style.transform=`scale(${1+opening*.07})`;const end=document.querySelector('.portal-end');end.style.opacity=String(ending);end.style.transform=`translateY(${(1-ending)*18}px)`;document.querySelector('.portal-scrim').style.opacity=String(Math.max(0,(p-.3)/.7));document.querySelector('.portal-mobile-wash').style.opacity=String(1-Math.min(1,p/.3));document.querySelector('.film-progress span').style.transform=`scaleX(${p})`;hero.classList.toggle('inside',p>.42);}
  async function init(){
    try{carouselModule=await import('./cinematic-carousel.js?v=3');if(stopped)return;carousel=carouselModule.createCinematicCarousel({root:document.querySelector('.cinema'),reduce:motionOff()});}catch(error){console.warn('Gallery enhancement unavailable.',error.message);}
    if(motionOff()||!window.gsap||!window.ScrollTrigger){hero.classList.add('is-static');hero.querySelector('.film-load-status').hidden=true;return;}gsap.registerPlugin(ScrollTrigger);document.documentElement.classList.add('has-sequence');hero.querySelector('.film-load-status').hidden=false;
    if(window.Lenis){lenis=new Lenis({lerp:.115,smoothWheel:true,wheelMultiplier:.9,syncTouch:false,anchors:{offset:-40}});lenis.on('scroll',ScrollTrigger.update);gsap.ticker.add(tick);gsap.ticker.lagSmoothing(500,33);}
    if(location.hash){const target=document.getElementById(decodeURIComponent(location.hash.slice(1)));if(target)requestAnimationFrame(()=>{if(lenis)lenis.scrollTo(target,{immediate:true,offset:-40});else target.scrollIntoView();});}
    motionContext=gsap.context(()=>{
      const intro=gsap.timeline({defaults:{ease:'power3.out'}});intro.from('.header',{y:-10,opacity:.5,duration:1},0).from('.portal-copy h1',{y:22,opacity:.45,duration:1.25,clearProps:'transform,opacity'},.08).from('.portal-copy>p,.portal-copy>.button',{y:18,opacity:.3,duration:1.05,stagger:.09,clearProps:'transform,opacity'},.25);
      document.querySelectorAll('.reveal').forEach(el=>{const words=splitHeading(el);gsap.fromTo(words,{yPercent:105,rotate:3,opacity:.15},{yPercent:0,rotate:0,opacity:1,duration:1.05,stagger:.055,ease:'power3.out',scrollTrigger:{trigger:el,start:'top 91%',once:true},clearProps:'transform,opacity'});});
      document.querySelectorAll('.manifesto-top,.manifesto-bottom,.section-heading>p,.cinema-heading>p,.inspiration-heading>p,.approach-copy>p,.approach-copy>.text-link,.contact-copy>p,.contact-copy>.phone-link,.contact-copy>.text-link,.footer-top').forEach(el=>gsap.from(el,{y:24,opacity:.2,duration:1.05,ease:'power3.out',scrollTrigger:{trigger:el,start:'top 93%',once:true},clearProps:'transform,opacity'}));
      [document.querySelector('.service-tabs'),document.querySelector('.approach-notes'),document.querySelector('.enquiry-form')].forEach(group=>gsap.from([...group.children].filter(el=>!el.hasAttribute('aria-hidden')),{y:22,opacity:.2,duration:.95,stagger:.08,ease:'power3.out',scrollTrigger:{trigger:group,start:'top 90%',once:true},clearProps:'transform,opacity'}));
      document.querySelectorAll('.detail-photo .image-wrap,.service-visual,.cinema-shell').forEach(el=>gsap.from(el,{y:45,opacity:.35,duration:1.3,ease:'power3.out',scrollTrigger:{trigger:el,start:'top 92%',once:true},clearProps:'transform,opacity'}));
      document.querySelectorAll('.detail-photo img,.celebration-banner img,.night-photo img').forEach(el=>gsap.fromTo(el,{yPercent:-5,scale:1.13},{yPercent:5,scale:1.13,ease:'none',scrollTrigger:{trigger:el.closest('figure,.celebration-banner'),start:'top bottom',end:'bottom top',scrub:.8}}));
      gsap.from('.celebration-copy>*',{y:35,opacity:.2,duration:1.1,stagger:.12,ease:'power3.out',scrollTrigger:{trigger:'.celebration-banner',start:'top 65%',once:true},clearProps:'transform,opacity'});
      gsap.from('.night-photo figcaption>*',{y:30,opacity:.3,duration:1.1,stagger:.1,ease:'power3.out',scrollTrigger:{trigger:'.night-photo',start:'top 65%',once:true},clearProps:'transform,opacity'});
      gsap.from('.footer-word',{yPercent:26,opacity:.25,duration:1.3,ease:'power3.out',scrollTrigger:{trigger:'.footer',start:'top 90%',once:true},clearProps:'transform,opacity'});
    });
    try{const {createPortalSequence}=await import('./portal-sequence.js?v=3');film=await createPortalSequence({hero,gsap,ScrollTrigger,onProgress:portalProgress});if(stopped||motionOff()){staticMotion();return;}}
    catch(error){console.warn('Invitation film unavailable; showing its poster.',error.message);document.documentElement.classList.remove('has-sequence');hero.classList.add('is-static');hero.querySelector('.film-load-status').hidden=true;}
    ScrollTrigger.refresh();document.fonts.ready.then(()=>ScrollTrigger.refresh());
  }
  function restoreHeadings(){splitHeadings.forEach(({el,original})=>{el.innerHTML=original;el.removeAttribute('aria-label');});splitHeadings.length=0;}
  function staticMotion(){document.documentElement.classList.add('motion-off');film?.destroy();motionContext?.revert();restoreHeadings();lenis?.destroy();window.gsap?.ticker.remove(tick);carousel?.destroy();if(carouselModule&&!stopped)carousel=carouselModule.createCinematicCarousel({root:document.querySelector('.cinema'),reduce:true});document.documentElement.classList.remove('has-sequence');hero.classList.add('is-static');hero.classList.remove('inside');document.querySelector('.portal-copy').removeAttribute('style');document.querySelector('.portal-end').style.opacity='0';document.querySelector('.portal-scrim').style.opacity='0';document.querySelector('.portal-mobile-wash').style.opacity='1';hero.querySelector('.film-load-status').hidden=true;}
  reduced.addEventListener('change',staticMotion);init();addEventListener('pagehide',()=>{stopped=true;film?.destroy();carousel?.destroy();motionContext?.revert();restoreHeadings();lenis?.destroy();window.gsap?.ticker.remove(tick);});
